mapper.sql:
WHERE tenant_id = #{tenantId}
  AND query_hash = #{queryHash}
  AND data_version = #{dataVersion}

    AND current_gmroi_role = #{currentGmroi}


    AND compare_gmroi_role = #{compareGmroi}




            AND promotion_flag = '1'


            AND (promotion_flag IS NULL OR promotion_flag = '0')




    AND product_status_no IN

        #{st}



    AND (


            gmroi <= 1
            gmroi > 1 AND gmroi <= 2
            gmroi > 2 AND gmroi <= 3
            gmroi > 3
            1 = 0


    )
